def transform(grid):
    h, w = len(grid), len(grid[0])
    fill = grid[1][1]

    # Divider lines are the rows and columns that form the colored grid.
    # Their spacing is determined by repeated separator signatures.
    def get_lines(n, signature):
        sig = [signature(i) for i in range(n)]
        best = None
        for p in range(2, min(n, 13)):
            score = sum(sig[i] == sig[i-p] for i in range(p, n))
            if best is None or score > best[0]:
                best = (score, p)
        p = best[1]
        return list(range(p // 2, n, p))

    rs = get_lines(h, lambda r: tuple(grid[r]))
    cs = get_lines(w, lambda c: tuple(grid[r][c] for r in range(h)))

    # Crossing markers form a reduced grid. Convert plain divider color
    # to the cell fill, then crop away blank outer crossings.
    vals = [[grid[r][c] for c in cs] for r in rs]
    vals = [[fill if x == grid[0][0] else x for x in row] for row in vals]
    while vals and all(x == fill for x in vals[0]):
        vals.pop(0)
    while vals and all(x == fill for x in vals[-1]):
        vals.pop()
    while vals and all(row[0] == fill for row in vals):
        for row in vals:
            row.pop(0)
    while vals and all(row[-1] == fill for row in vals):
        for row in vals:
            row.pop()
    return vals
